const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',folder:'M3 7V5a1 1 0 0 1 1-1h5l2 3h9a1 1 0 0 1 1 1v11H3z',tasks:'M9 5h11v15H4V5h2 M9 3h6v4H9z M8 12l2 2 5-5',mail:'M3 5h18v14H3z M3 5l9 8 9-8',calendar:'M4 5h16v16H4z M4 9h16 M8 3v4 M16 3v4 M8 13h3 M8 17h7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',chart:'M4 20V12h3v8z M10 20V8h3v12z M16 20V4h3v16z',files:'M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6 M9 16h6',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',link:'M10 13l4-4 M8 15l-2 2a3 3 0 0 1-4-4l5-5a3 3 0 0 1 4 0 M16 9l2-2a3 3 0 0 1 4 4l-5 5a3 3 0 0 1-4 0',user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a8 6 0 0 1 16 0v3z',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',plus:'M12 5v14 M5 12h14',check:'M4 12l5 5L20 6',arrow:'M5 12h14 M14 7l5 5-5 5',close:'M5 5l14 14 M19 5L5 19',menu:'M3 6h18 M3 12h18 M3 18h18',bell:'M6 16V9a6 6 0 0 1 12 0v7l2 2H4z M10 21h4',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v3 M12 20v3 M1 12h3 M20 12h3 M4 4l2 2 M18 18l2 2 M20 4l-2 2 M6 18l-2 2',logout:'M9 3H4v18h5 M9 12h12 M16 7l5 5-5 5',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',edit:'M4 17l12-12 4 4-12 12H4z M14 7l4 4',trash:'M4 6h16 M8 6V3h8v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',external:'M14 3h7v7 M21 3L10 14 M10 5H4v15h15v-6',pause:'M8 4v16 M16 4v16',play:'M7 4l13 8-13 8z',stop:'M5 5h14v14H5z',shield:'M12 3l8 3v6c0 6-8 9-8 9s-8-3-8-9V6z M8 12l3 3 5-6',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M9 9a3 3 0 1 1 5 2l-2 2 M12 16v1',refresh:'M20 8a8 8 0 1 0 0 9 M20 3v6h-6'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,action,cls='',ico='')=>`<button class="${cls}" data-action="${esc(action)}">${ico?icon(ico):''}${label}</button>`;
const tag=(s,cls='')=>`<span class="tag ${cls}">${esc(s)}</span>`;
const statuses=['To Do','In Progress','Waiting for Client','Completed'];
const pages=[['dashboard','Dashboard','grid'],['clients','Clients & Projects','folder'],['tasks','Task Board','tasks'],['followups','Follow-up Center','bell'],['inbox','Inbox','mail'],['calendar','Calendar','calendar'],['time','Time Tracker','clock'],['reports','Daily Reports','chart'],['templates','Templates & Files','files'],['ai','AI Assistant','spark'],['apps','Connected Apps','link'],['account','My Account','user']];
let previewMode=false;
let user=null,csrf='',data={},integrations={},page='dashboard',filter='',search='',tab='templates',selectedMail=null,mails=[],aiText='',aiPrompt='',mailDraft=null,calendarMonth=new Date(),calendarLive=[],driveFiles=[],busy=false,refreshId=0;
const app=$('#app'),modal=$('#modal');
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.className='',4500)}
async function api(path,method='GET',value){const r=await fetch(path,{method,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...(method==='POST'&&path.startsWith('/api/records/')?{'Idempotency-Key':crypto.randomUUID()}: {})},...(value!==undefined?{body:JSON.stringify(value)}:{})});let x;try{x=await r.json()}catch{const e=Error('The private backend is not connected to this website yet.');e.backendUnavailable=true;throw e}if(x.code==='BACKEND_UNAVAILABLE'){const e=Error(x.error);e.backendUnavailable=true;throw e}if(!r.ok){if(r.status===401&&user){user=null;auth(false)}throw Error(x.error||'Request failed.')}return x}
const getList=k=>data[k]||[];
const cname=id=>getList('clients').find(c=>c.id===id)?.name||'General';
const currentDay=()=>new Intl.DateTimeFormat('en-CA',{timeZone:user?.timezone||'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dayOf=t=>new Intl.DateTimeFormat('en-CA',{timeZone:user?.timezone||'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t));
const dateStr=(t,opts={month:'short',day:'numeric'})=>t?new Date(t.length===10?t+'T12:00:00':t).toLocaleDateString('en-US',{...opts,timeZone:user?.timezone||'Asia/Manila'}):'No date';
const clockStr=t=>new Date(t).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:user?.timezone||'Asia/Manila'});
const duration=seconds=>{const s=Math.max(0,Math.floor(seconds||0));return `${Math.floor(s/3600)}h ${Math.floor(s%3600/60)}m`};
const hms=seconds=>{const s=Math.max(0,Math.floor(seconds||0));return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(x=>String(x).padStart(2,'0')).join(':')};
const find=(k,id)=>getList(k).find(r=>r.id===id);
const matches=r=>!search||JSON.stringify(r).toLowerCase().includes(search.toLowerCase());
function empty(title,description,action='',label='Add your first item',ico='folder'){return `<div class="empty">${icon(ico)}<strong>${esc(title)}</strong>${esc(description)}${action?'<br>'+btn(label,action,'primary small','plus'):''}</div>`}
function card(title,content,ico='',action=''){return `<section class="card"><div class="card-head"><h2>${ico?icon(ico):''}${title}</h2>${action}</div><div class="card-body">${content}</div></section>`}
function heading(title,subtitle,buttons=''){return `<div class="heading"><div><div class="eyebrow">YOUR PERSONAL WORKSPACE</div><h1>${title}</h1><div class="muted">${subtitle}</div></div><div class="row wrap">${buttons}</div></div>`}
function auth(setup){app.innerHTML=`<div class="auth"><aside class="auth-art"><div class="brand"><div class="brand-mark">V</div><div><strong>Cliff’s Workspace</strong><small>VIRTUAL ASSISTANT SUITE</small></div></div><div class="eyebrow">A LITTLE CALM. A LOT DONE.</div><h1>Your clients, tasks<br>and workday.<br>Beautifully together.</h1><p>A thoughtful space to plan your day, serve your clients, and make room for your best work.</p><div class="auth-badges"><span>Organized by client</span><span>Built for your workday</span></div></aside><section class="auth-form"><form id="auth-form"><div class="eyebrow">WELCOME ${setup?'TO YOUR NEW WORKSPACE':'BACK'}</div><h1>${setup?'Make it yours.':'Your workspace awaits.'}</h1><p class="muted">${setup?'Create your private owner account to get started.':'Sign in to pick up right where you left off.'}</p>${setup?'<div class="field"><label for="name">Full name</label><input id="name" name="name" value="Cliff Jandee Medrano" required maxlength="100" autocomplete="name"></div>':''}<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" required autocomplete="email"></div><div class="field"><label for="password">Password ${setup?'(12 characters minimum)':''}</label><div class="password-field"><input id="password" name="password" type="password" required minlength="${setup?12:1}" maxlength="128" autocomplete="${setup?'new-password':'current-password'}">${btn('Show','toggle-password','small')}</div></div>${setup?'<div class="field"><label for="setupCode">Private setup code</label><input id="setupCode" name="setupCode" type="password" required autocomplete="off"><small class="muted">The SETUP_CODE you configured on your server.</small></div>':''}<div class="auth-error" role="alert"></div><button type="submit" class="primary">${setup?'Create my workspace':'Sign in'} ${icon('arrow')}</button><p class="quiet mt">${icon('shield')} Your workspace uses a private account and server-stored records.</p></form></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;$('.auth-error').textContent='';try{const x=await api('/api/auth/'+(setup?'register':'login'),'POST',Object.fromEntries(new FormData(e.target)));user=x.user;csrf=x.csrf;await load();shell()}catch(err){$('.auth-error').textContent=err.message}finally{b.disabled=false}}}
async function load(){[data,integrations]=await Promise.all([api('/api/data'),api('/api/integrations')])}
function shell(){page=location.hash.slice(1)||'dashboard';if(!pages.some(x=>x[0]===page))page='dashboard';app.innerHTML=`<div class="mobile-overlay" data-action="menu"></div><aside class="sidebar"><button class="ghost menu-close" data-action="menu" aria-label="Close navigation">${icon('close')}</button><div class="brand"><div class="brand-mark">V</div><div><strong>Cliff’s Workspace</strong><small>VIRTUAL ASSISTANT SUITE</small></div></div><nav class="nav" aria-label="Main navigation">${pages.map(([id,label,ico],i)=>`${i===9?'<div class="label">YOUR TOOLS</div>':''}<button data-page="${id}">${icon(ico)}${label}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">One workspace. A more focused day.</div><div class="profile-mini"><span class="avatar">${esc(initials(user.name))}</span><div><strong>${esc(user.name)}</strong><small>Virtual Assistant</small></div><button class="ghost" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar">${btn('','menu','ghost mobile-menu','menu')}<div class="breadcrumbs">Workspace <span> / </span> <b id="crumb"></b></div><div class="top-actions"><div class="search">${icon('search')}<input id="global-search" aria-label="Search workspace" placeholder="Search tasks, clients, files…" value="${esc(search)}"></div><button class="ghost" data-action="notifications" aria-label="Show reminders">${icon('bell')}</button><span class="avatar">${esc(initials(user.name))}</span></div></header><div class="content">${previewMode?`<div class="notice" role="status">${icon('help')}<div><strong>Design preview · Sample data</strong> · Saving and connections unavailable.</div>${btn('Connection setup','pages-help','small')}</div>`:''}<div id="view"></div><footer class="footer"><span>Cliff’s VA Workspace · A little more organized, every day.</span><span>${esc(user.timezone)} <span class="pill">${previewMode?'Preview only':'Private workspace'}</span></span></footer></div></main>`;$('#global-search').oninput=e=>{search=e.target.value;clearTimeout(shell.searchTimer);shell.searchTimer=setTimeout(render,170)};render();if(new URLSearchParams(location.search).has('connection')){toast(new URLSearchParams(location.search).get('connection')==='success'?'Google account connected.':'Connection cancelled.');history.replaceState(null,'','/#apps')}}
function initials(s){return s.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function navigate(id){if(page===id)return;search='';filter='';if($('#global-search'))$('#global-search').value='';location.hash=id;$('.sidebar')?.classList.remove('open');$('.mobile-overlay')?.classList.remove('open')}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'dashboard';render();loadGmailOnOpen()});
function render(){if(!user||!$('#view'))return;document.body.dataset.page=page;refreshId++;if(!pages.some(x=>x[0]===page))page='dashboard';$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});$('#crumb').textContent=pages.find(x=>x[0]===page)[1];const views={dashboard,clients:clientsView,tasks:tasksView,followups:followupView,inbox:inboxView,calendar:calendarView,time:timeView,reports:reportsView,templates:templatesView,ai:aiView,apps:appsView,account:accountView};$('#view').innerHTML=`<div class="page">${views[page]()}</div>`;updateTimer();bindPage();if(previewMode){$$('#view input, #view select, #view textarea').forEach(x=>x.disabled=true);$$('[data-action]').forEach(b=>{if(/^(add:|complete:|checklist:|timer-|logout|sample|compose|gmail-load|google-|disconnect:|connect:)/.test(b.dataset.action)){b.disabled=true;b.title='Connect the private backend to enable this action.'}});$$('#view button[type=submit]').forEach(b=>b.disabled=true)}}
function taskLine(t){return `<div class="task-line"><button class="check ${t.status==='Completed'?'done':''}" data-action="complete:${t.id}" aria-label="${t.status==='Completed'?'Reopen':'Complete'} ${esc(t.title)}">${t.status==='Completed'?icon('check'):''}</button><div class="grow"><div class="task-name"><button class="text-link" data-action="detail:tasks:${t.id}">${esc(t.title)}</button></div><div class="muted">${esc(cname(t.client))} · ${t.due?dateStr(t.due):'No deadline'}</div></div><span class="tag ${t.priority==='High'?'red':t.priority==='Medium'?'gold':''}">${esc(t.priority||'Normal')}</span></div>`}
function dashboard(){const today=currentDay(),pending=getList('tasks').filter(t=>t.status!=='Completed'),done=getList('tasks').filter(t=>t.status==='Completed'),todayTasks=pending.filter(t=>!t.due||t.due<=today),seconds=getList('time').filter(t=>t.date===today).reduce((n,t)=>n+Number(t.seconds),0),events=getList('events').filter(e=>dayOf(e.start)===today).sort((a,b)=>a.start.localeCompare(b.start));return heading(`Good ${Number(new Intl.DateTimeFormat('en-GB',{timeZone:user.timezone,hour:'2-digit',hourCycle:'h23'}).format(new Date()))<12?'morning':Number(new Intl.DateTimeFormat('en-GB',{timeZone:user.timezone,hour:'2-digit',hourCycle:'h23'}).format(new Date()))<18?'afternoon':'evening'}, ${esc(user.name.split(' ')[0])}.`,`Here’s your work overview for ${dateStr(today,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}.`,btn('Start my day','startday','','sun')+btn('Add task','add:tasks','primary','plus'))+
 (!getList('clients').length&&!getList('tasks').length?`<div class="notice">${icon('spark')}<div><strong>Your fresh start is ready.</strong><br>Add your own records, or explore the design using clearly labelled sample data.</div>${btn('Load sample data','sample','small')}</div>`:'')+
 `<div class="grid stats">${[['tasks','Tasks today',todayTasks.length],['folder','Active clients',getList('clients').filter(c=>c.status!=='Completed').length],['clock','Time today',duration(seconds)],['check','Completed tasks',done.length]].map(([i,l,v])=>`<div class="card stat"><span class="stat-icon">${icon(i)}</span><div><div class="muted">${l}</div><div class="value">${v}</div></div></div>`).join('')}</div><div class="grid dashboard-main">${card('Today’s priorities',todayTasks.slice(0,4).map(taskLine).join('')||empty('A clear day ahead','Add a task to plan your next step.','add:tasks','Add task','tasks'),'tasks',btn('View all','goto:tasks','ghost small'))}${timerCard()}${card('Today’s agenda',events.length?`<div class="agenda">${events.slice(0,4).map(e=>`<div class="agenda-item"><div class="agenda-time">${clockStr(e.start)}</div><div><div class="agenda-title">${esc(e.title)}</div><div class="muted">${esc(cname(e.client))} · ${Math.round((Date.parse(e.end)-Date.parse(e.start))/60000)} min</div></div></div>`).join('')}</div>`:empty('Room to focus','No meetings scheduled today.','add:events','Add meeting','calendar'),'calendar',btn('','goto:calendar','ghost small','arrow'))}</div><div class="grid dashboard-bottom">${card('Your week at a glance',weeklyChart(),'chart',`<span class="muted">Tracked hours</span>`)}${card('AI Assistant',`<p class="muted">A helping hand for emails, summaries, and your daily report.</p><div class="quick-actions">${btn('Draft an email','ai-preset:email','','mail')}${btn('Summarize notes','ai-preset:summary','','files')}${btn('Prepare daily report','finishday','','chart')}</div>`,'spark')}${card('Connected apps',`<p class="muted">Bring your work tools into one place.</p><div class="app-chips">${['gmail','calendar','drive'].map(k=>`<span class="app-chip ${integrations[k]?.connected?'on':''}"><i></i>${k==='gmail'?'Gmail':k==='drive'?'Drive':'Calendar'}</span>`).join('')}</div><p class="quiet mt">${Object.values(integrations).filter(x=>x.connected).length} Google services connected</p>${btn('Manage apps','goto:apps','small','link')}`,'link')}</div>`}
function weeklyChart(){const days=[];const now=new Date(currentDay()+'T12:00:00');const dow=(now.getDay()+6)%7;now.setDate(now.getDate()-dow);for(let i=0;i<7;i++){const d=new Date(now);d.setDate(d.getDate()+i);const key=localDate(d);const sec=getList('time').filter(t=>t.date===key).reduce((n,t)=>n+Number(t.seconds),0);days.push({day:d.toLocaleDateString('en',{weekday:'short'}),sec})}const max=Math.max(3600,...days.map(x=>x.sec));return `<div class="row spread"><div class="muted">A steady rhythm, one day at a time.</div><strong>${duration(days.reduce((n,d)=>n+d.sec,0))}</strong></div><div class="chart">${days.map(d=>`<div class="bar-col"><small>${d.sec?duration(d.sec):''}</small><div class="bar" style="height:${Math.max(2,d.sec/max*100)}%"></div><span>${d.day}</span></div>`).join('')}</div>`}
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
// The timer is a server-stored singleton. Navigation never restarts it.
function timerState(){return getList('timer')[0]||null}
function timerSeconds(){const t=timerState();return (Number(t?.elapsed)||0)+(t?.running?Math.max(0,Math.floor((Date.now()-t.started)/1000)):0)}
function timerCard(){const t=timerState();return `<section class="card timer-card"><div class="card-head"><h2>${icon('clock')}Active time tracker</h2><span class="live">${t?.running?'Tracking':'Ready to focus'}</span></div><div class="card-body"><div class="timer-clock" data-timer>${hms(timerSeconds())}</div><div class="field"><label for="timer-client">Client</label><select id="timer-client" ${t?.running?'disabled':''}>${clientOptions(t?.client)}</select></div><div class="field"><label for="timer-title">What are you working on?</label><input id="timer-title" placeholder="Choose your next focus…" value="${esc(t?.title||'')}" ${t?.running?'disabled':''}></div><div class="row">${btn(t?.running?'Pause':'Start',t?.running?'timer-pause':'timer-start','primary',t?.running?'pause':'play')}${btn('Save & stop','timer-stop','','stop')}</div>${t?btn('Discard session','timer-discard-request','ghost small mt'):''}</div></section>`}
function updateTimer(){$$('[data-timer]').forEach(el=>el.textContent=hms(timerSeconds()))}setInterval(updateTimer,1000);
function clientOptions(id=''){return `<option value="">General / No client</option>`+getList('clients').map(c=>`<option value="${c.id}" ${id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}
function clientFilter(){return `<select id="client-filter" aria-label="Filter by client" class="filter-select"><option value="">All clients</option>${getList('clients').map(c=>`<option value="${c.id}" ${filter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`}
function clientsView(){const list=getList('clients').filter(matches);return heading('Clients & projects.','A dedicated place for every client, project, and important detail.',btn('Add client','add:clients','primary','plus'))+`<div class="grid cards-3">${list.map(c=>{const ts=getList('tasks').filter(t=>t.client===c.id),pct=ts.length?Math.round(ts.filter(t=>t.status==='Completed').length/ts.length*100):0;return `<article class="card"><div class="card-body"><div class="row spread"><div class="row"><span class="client-monogram">${esc(initials(c.name))}</span><div><h3><button class="text-link" data-action="workspace:${c.id}">${esc(c.name)}</button></h3><span class="muted">${esc(c.project||'Client workspace')}</span></div></div>${tag(c.status||'Active')}</div><div class="client-contact mt">${icon('mail')}${esc(c.email||'No email added')}</div><div class="client-contact">${icon('user')}${esc(c.contact||'No contact added')}</div><div class="row spread mt"><span class="muted">Task progress</span><small>${pct}%</small></div><div class="progress"><div style="width:${pct}%"></div></div><strong class="quiet">Instructions</strong><p class="instructions clamp">${esc(c.instructions||'Add client preferences and project instructions.')}</p><div class="row spread">${btn('Open workspace','workspace:'+c.id,'small','folder')}${btn(previewMode?'View details':'Edit','edit:clients:'+c.id,'ghost small',previewMode?'files':'edit')}</div>${c.sample?'<div class="quiet mt">Sample client</div>':''}</div></article>`}).join('')}</div>`+(list.length?'':empty('Your clients belong here','Keep instructions, contacts and work in one organized place.','add:clients','Add client'))}
function tasksView(){let list=getList('tasks').filter(matches).filter(t=>!filter||t.client===filter);return heading('A little progress, every day.','Move your work forward, from the first idea to the final check.',btn('Add task','add:tasks','primary','plus'))+`<div class="toolbar">${clientFilter()}<span class="muted">${list.length} tasks · Changes save immediately</span></div><div class="board">${statuses.map((status,index)=>`<section class="board-col"><div class="board-head">${status} ${tag(list.filter(t=>t.status===status).length)}</div>${list.filter(t=>t.status===status).map(t=>`<article class="task-card"><div class="row spread"><span class="quiet">${esc(cname(t.client))}</span><button class="ghost small" data-action="edit:tasks:${t.id}" aria-label="Edit task">${icon('edit')}</button></div><h3><button class="text-link" data-action="detail:tasks:${t.id}">${esc(t.title)}</button></h3>${tag(t.priority||'Normal',t.priority==='High'?'red':t.priority==='Medium'?'gold':'')}<div class="task-meta">${icon('calendar')}${t.due?esc(dateStr(t.due)):'No deadline'}${t.sample?' · Sample':''}</div><select data-status="${t.id}" aria-label="Status for ${esc(t.title)}">${statuses.map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></article>`).join('')||'<p class="empty-mini">A little room for your next task.</p>'}${btn('Add task','add-task-status:'+index,'ghost small','plus')}</section>`).join('')}</div>`}
function followupView(){const today=currentDay(),waiting=getList('tasks').filter(t=>t.status==='Waiting for Client'&&matches(t)),overdue=getList('tasks').filter(t=>t.status!=='Completed'&&t.due&&t.due<today&&matches(t));return heading('Nothing slips through.','Keep pending approvals, overdue work, and next steps in sight.',btn('Add follow-up','add-followup','primary','plus'))+`<div class="grid cards-2">${card('Waiting for client',waiting.map(taskLine).join('')||empty('All caught up','No pending client approvals.','','','check'),'clock')}${card('Overdue tasks',overdue.map(taskLine).join('')||empty('A clean slate','No overdue tasks.','','','check'),'bell')}</div>`}
function calendarView(){const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1),start=new Date(first);start.setDate(1-((first.getDay()+6)%7));const cells=[];for(let i=0;i<42;i++){const d=new Date(start);d.setDate(d.getDate()+i);const key=localDate(d),events=getList('events').filter(e=>dayOf(e.start)===key&&matches(e));cells.push(`<div class="day-cell ${key===currentDay()?'today':''}"><div class="day-number">${d.getMonth()===m?'<strong>':''}${d.getDate()}${d.getMonth()===m?'</strong>':''}</div>${events.map(e=>`<button class="calendar-event" data-action="edit:events:${e.id}">${clockStr(e.start)}<br>${esc(e.title)}</button>`).join('')}</div>`)}return heading('Make time for what matters.','Meetings, deadlines, and room to focus. All in your timezone.',(previewMode||integrations.calendar?.connected?btn('View Google events','google-calendar','','refresh'):btn('Connect Google Calendar',integrations.calendar?.configured?'connect:calendar':'setup-help','','link'))+btn('Add meeting','add:events','primary','plus'))+`<div class="card"><div class="card-head"><h2>${calendarMonth.toLocaleDateString('en',{month:'long',year:'numeric'})}</h2><div class="row">${btn('‹','month-prev','small')}${btn('Today','month-now','small')}${btn('›','month-next','small')}<span class="muted">${esc(user.timezone)}</span></div></div><div class="table-wrap"><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="calendar-head">${d}</div>`).join('')}${cells.join('')}</div></div></div>`}
function timeView(){const entries=getList('time').filter(matches).filter(t=>!filter||t.client===filter);return heading('Your time, thoughtfully tracked.','Focus on the work. Keep a clear record of every hour.',btn('Export CSV','time-export','','download')+btn('Log manual time','add:time','primary','plus'))+`<div class="grid time-layout"><div>${timerCard()}</div><section class="card"><div class="card-head"><h2>Timesheet</h2><strong>${duration(entries.reduce((n,t)=>n+Number(t.seconds),0))}</strong></div><div class="card-body">${clientFilter()}</div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Client / Task</th><th>Duration</th><th></th></tr></thead><tbody>${entries.map(t=>`<tr><td>${dateStr(t.date)}</td><td class="long"><button class="text-link" data-action="detail:time:${t.id}">${esc(t.title||'Work session')}</button><div class="muted">${esc(cname(t.client))}</div></td><td>${duration(t.seconds)}</td><td>${btn('','edit:time:'+t.id,'ghost small','edit')}</td></tr>`).join('')}</tbody></table>${entries.length?'':empty('Your next focus session starts here','Start the timer or log your hours manually.','','','clock')}</div></section></div>`}
function reportText(r){return `Daily Work Report\n${user.name} · ${r.date}\n\nCompleted Work\n${r.completed||'—'}\n\nPending Items\n${r.pending||'—'}\n\nBlockers\n${r.blockers||'None'}\n\nNext Steps\n${r.next||'—'}\n\nTracked time: ${duration(r.seconds||0)}`}
function reportsView(){return heading('End your day with clarity.','A thoughtful update for your clients, ready to review and share.',btn('Finish my day','finishday','','sun')+btn('Create report','add:reports','primary','plus'))+`<div class="grid cards-2">${getList('reports').filter(matches).map(r=>`<article class="card"><div class="card-head"><h2>${dateStr(r.date,{weekday:'short',month:'short',day:'numeric'})}</h2>${tag(duration(r.seconds||0))}</div><div class="card-body"><h3>Completed work</h3><p class="report-content clamp">${esc(r.completed||'No completed work added.')}</p><h3 class="mt">Next steps</h3><p class="report-content clamp">${esc(r.next||'No next steps added.')}</p><div class="row wrap mt">${btn('Preview','report-preview:'+r.id,'small','files')}${btn(previewMode?'View details':'Edit','edit:reports:'+r.id,'small',previewMode?'files':'edit')}${btn('Export','report-export:'+r.id,'ghost small','download')}</div></div></article>`).join('')}</div>`+(getList('reports').length?'':empty('A great day deserves a clear report','Build a report from your completed work, then add your notes.','finishday','Prepare report','chart'))}
function templatesView(){return heading('Your go-to tools, within reach.','Reusable emails, clear checklists, and important work links.',(tab==='files'&&!previewMode?btn(integrations.drive?.connected?'Open Google Drive':'Connect Google Drive',integrations.drive?.connected?'google-drive':integrations.drive?.configured?'connect:drive':'setup-help','','link')+btn(integrations.sheets?.connected?'Open Google Sheets':'Connect Google Sheets',integrations.sheets?.connected?'google-sheets':integrations.sheets?.configured?'connect:sheets':'setup-help','','link'):'')+btn('Add '+(tab==='files'?'file link':tab==='checklist'?'checklist item':'template'),'add:'+tab,'primary','plus'))+`<div class="tabs">${[['templates','Email templates & SOPs'],['files','File links'],['checklist','Daily checklist']].map(([id,l])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${l}</button>`).join('')}</div>`+(tab==='checklist'?card('Daily work checklist',getList('checklist').filter(matches).map(c=>`<div class="task-line"><button class="check ${c.doneDate===currentDay()?'done':''}" data-action="checklist:${c.id}" aria-label="Toggle ${esc(c.title)}">${c.doneDate===currentDay()?icon('check'):''}</button><span>${esc(c.title)}</span><span style="margin-left:auto">${btn('Edit','edit:checklist:'+c.id,'ghost small','edit')}</span></div>`).join('')||empty('Build your daily rhythm','Your checklist resets automatically each day.','add:checklist','Add checklist item'),'tasks'):`<div class="grid cards-3">${getList(tab).filter(matches).map(r=>`<article class="card"><div class="card-body"><div class="row spread mb">${icon(tab==='files'?'folder':'files')}${tag(r.category||'Resource')}</div><h3>${esc(r.title)}</h3><p class="muted clamp">${esc(r.body||r.url||'')}</p><div class="row wrap mt">${tab==='files'&&r.sample?btn('View details','detail:files:'+r.id,'small','files'):tab==='files'?`<a class="link-text" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Open file ↗</a>`:btn('View / copy','template-view:'+r.id,'small','files')}${btn('Edit','edit:'+tab+':'+r.id,'ghost small','edit')}</div></div></article>`).join('')}</div>`+(!getList(tab).length?empty('A home for your resources','Add reusable templates or secure links to your work files.','add:'+tab,'Add resource','files'):''))}
function appsView(){const definitions=[['gmail','G','Gmail','Read your inbox · Draft replies · Send reviewed emails'],['calendar','▦','Google Calendar','View upcoming meetings · Create events in your calendar'],['drive','△','Google Drive','Find files · Open secure Drive links · Save links to your workspace'],['sheets','▤','Google Sheets','Read a range · Append rows · Keep trackers updated'],['openai','✧','AI Assistant','Draft emails · Summarize notes · Prepare report text']];return heading('Your favorite tools. Together.','Connect your own accounts and choose what your workspace can access.',btn('Setup guide','setup-help','','help'))+`<div class="notice">${icon('shield')}<div>Sign in through Google’s official page. Your Google password is never entered or stored here. AI uses a separate server-side API key.</div></div><div class="grid cards-3">${definitions.map(([key,symbol,name,desc])=>{const i=integrations[key]||{},on=key==='openai'?i.configured:i.connected;return `<section class="card integration"><div class="card-body"><div class="row spread mb"><span class="app-icon">${symbol}</span>${tag(on?'Ready':i.configured?'Not connected':'Setup required',on?'':'gold')}</div><h3>${name}</h3><ul>${desc.split(' · ').map(l=>`<li>${l}</li>`).join('')}</ul>${key==='openai'?'<div class="quiet">Separate API usage billing. No personal ChatGPT history is imported.</div>':`<div class="connection-account">${esc(i.email||'No account linked')}</div>`}<div class="row wrap">${key==='openai'?btn(i.configured?'Open assistant':'Setup instructions',i.configured?'goto:ai':'setup-help','primary small'):on?btn('Open',key==='gmail'?'goto:inbox':key==='calendar'?'google-calendar':key==='drive'?'google-drive':'google-sheets','primary small')+btn('Disconnect','disconnect:'+key,'small danger'):btn(i.configured?'Connect '+name:'Configure connection',i.configured?'connect:'+key:'setup-help','primary small','link')}</div></div></section>`}).join('')}${card('Other apps',`<p class="muted">Save a useful work app as a shortcut. Additional integrations need their own supported connection.</p>${btn('Add app shortcut','app-shortcut','small','plus')}`,'plus')}</div>`+card('How account connection works',`<div class="steps"><div class="step"><b>01 · Connect</b>Select the Google service you need.</div><div class="step"><b>02 · Sign in</b>Choose your account on Google’s website.</div><div class="step"><b>03 · Review access</b>Approve the requested permissions.</div><div class="step"><b>04 · Back to work</b>Use the connected service in your workspace.</div></div>`,'link')}
function inboxView(){return heading('A clearer inbox.','Read your latest messages, prepare a thoughtful reply, and turn requests into tasks.',btn('Refresh inbox','gmail-load','','refresh')+btn('Saved drafts','drafts-view','','files')+btn('Compose','compose','primary','mail'))+(!integrations.gmail?.connected&&!previewMode?card('Connect your inbox',empty('Bring your Gmail into your workspace',integrations.gmail?.configured?'Connect your Google account to load your inbox.':'Google OAuth setup is required before you can connect your Gmail account.',integrations.gmail?.configured?'connect:gmail':'gmail-setup','Connect Gmail','mail'),'mail'):`<div class="grid inbox-layout"><section class="card mail-list">${mails.length?mails.filter(matches).map(m=>`<button class="mail-item ${selectedMail?.id===m.id?'active':''}" data-action="mail:${m.id}"><strong>${esc(m.subject)}</strong><small>${esc(m.from)}</small><small>${esc(m.snippet)}</small></button>`).join(''):empty('Ready when you are','Load your latest 15 inbox messages.','gmail-load','Load inbox','mail')}</section><section class="card"><div class="card-body">${selectedMail?`<div class="eyebrow">SELECTED EMAIL · PREVIEW</div>${previewMode?'<p class="quiet">Sample email · Gmail is not connected</p>':''}<h2 class="mb">${esc(selectedMail.subject)}</h2><p class="muted">${esc(selectedMail.from)}</p><div class="mail-body">${esc(selectedMail.snippet)}</div><div class="quiet mt">Inbox preview only. Open Gmail to read the full conversation.</div><div class="row wrap mt"><a class="link-text" target="_blank" rel="noopener" href="https://mail.google.com/mail/u/?authuser=${encodeURIComponent(integrations.gmail.email||'')}#inbox/${encodeURIComponent(selectedMail.id)}">Open full email ↗</a>${btn('Create task','mail-task','small','tasks')}</div><div class="divider"></div><h3>AI writing assistant</h3><p class="muted">Only this email preview will be sent when you choose an AI action.</p><div class="row wrap">${btn('Draft reply','mail-ai:reply','small','spark')}${btn('Summarize','mail-ai:summary','small','files')}</div>${mailDraft?`<div class="ai-output mt">${esc(mailDraft)}</div>${btn('Edit & review reply','mail-review','primary small mt','mail')}`:''}`:empty('A little space for your next reply','Select an email from the list.','','','mail')}</div></section></div>`)}
function aiView(){return heading('A thoughtful helping hand.','Draft, organize, and find the words. You stay in control of every action.',btn('Connected apps','goto:apps','','link'))+`<div class="grid cards-2"><section class="card"><div class="card-body"><div class="row mb"><div class="ai-bubble">${icon('spark')}</div><div><h2>Your AI Assistant</h2><span class="muted">${integrations.openai?.configured?'Ready to help':'Configure your server API key to enable AI'}</span></div></div><div class="row wrap mb">${btn('Email draft','ai-preset:email','small')}${btn('Summarize notes','ai-preset:summary','small')}${btn('Meeting → tasks','ai-preset:meeting','small')}</div><form id="ai-form"><div class="field"><label for="ai-prompt">What would you like help with?</label><textarea id="ai-prompt" name="prompt" rows="10" required maxlength="10000" placeholder="Write your request and paste any notes you want the assistant to use…">${esc(aiPrompt)}</textarea></div><p class="quiet">Only the text you submit is sent to the AI service. Review generated content before using it.</p><button class="primary" type="submit">${icon('spark')} Generate draft</button></form></div></section>${card('Your draft',`<div class="ai-output" id="ai-result">${esc(aiText||'Your draft will appear here. Nothing is sent or changed automatically.')}</div><div class="row wrap mt">${btn('Copy text','ai-copy','small','files')}${btn('Save as template','ai-save','small','plus')}</div>`,'files')}</div>`}
function accountView(){return heading('Your workspace, your way.','Keep your details, work preferences, and account security up to date.')+`<div class="grid cards-2"><section class="card"><div class="card-head"><h2>${icon('user')} Personal profile</h2></div><div class="card-body"><div class="row mb"><span class="avatar">${esc(initials(user.name))}</span><div><strong>${esc(user.name)}</strong><div class="muted">${esc(user.email)}</div></div></div><form id="profile-form"><div class="field"><label for="profile-name">Full name</label><input id="profile-name" name="name" value="${esc(user.name)}" required maxlength="100"></div><div class="field"><label for="profile-timezone">Timezone</label><select id="profile-timezone" name="timezone">${['Asia/Manila','America/New_York','America/Chicago','America/Los_Angeles','Europe/London','Australia/Sydney','UTC'].map(z=>`<option ${z===user.timezone?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label for="profile-hours">Working hours</label><input id="profile-hours" name="hours" value="${esc(user.hours)}" maxlength="200"></div><button class="primary" type="submit">Save profile</button></form></div></section><div class="stack">${card('Account security',`<form id="password-form"><div class="field"><label for="current-password">Current password</label><input id="current-password" type="password" name="current" required autocomplete="current-password"></div><div class="field"><label for="new-password">New password</label><input id="new-password" type="password" name="password" required minlength="12" maxlength="128" autocomplete="new-password"></div><button class="primary" type="submit">Update password</button></form>`,'shield')}${card('Your data',`<p class="muted">Download a copy of your workspace records. Connection tokens and passwords are excluded.</p>${btn('Export workspace JSON','backup','','download')}<div class="divider"></div>${btn('View work history','history','','clock')}`,'files')}</div></div>`}
function bindPage(){const sel=$('#client-filter');if(sel)sel.onchange=e=>{filter=e.target.value;render()};$$('[data-status]').forEach(el=>el.onchange=async e=>{e.target.disabled=true;try{await save('tasks',{...find('tasks',el.dataset.status),status:e.target.value});render();toast('Task status updated.')}catch(err){render();toast(err.message,true)}});$$('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;render()});if($('#ai-form'))$('#ai-form').onsubmit=async e=>{e.preventDefault();aiPrompt=$('#ai-prompt').value;await withBusy(e.submitter,async()=>{const x=await api('/api/ai','POST',{prompt:aiPrompt});aiText=x.text;$('#ai-result').textContent=aiText})};if($('#profile-form'))$('#profile-form').onsubmit=async e=>{e.preventDefault();await withBusy(e.submitter,async()=>{user=await api('/api/profile','PUT',Object.fromEntries(new FormData(e.target)));shell();toast('Profile saved.')})};if($('#password-form'))$('#password-form').onsubmit=async e=>{e.preventDefault();await withBusy(e.submitter,async()=>{await api('/api/password','PUT',Object.fromEntries(new FormData(e.target)));e.target.reset();toast('Password updated.')})}}
async function withBusy(button,fn){if(button?.disabled)return;if(button)button.disabled=true;try{await fn()}catch(e){toast(e.message,true)}finally{if(button)button.disabled=false}}
async function save(kind,record){const id=record.id;const x=await api('/api/records/'+kind+(id?'/'+id:''),id?'PUT':'POST',record);const list=getList(kind);data[kind]=id?list.map(r=>r.id===id?x:r):[x,...list];return x}
function showModal(title,body,footer='',subtitle=''){if(modal.open)modal.close();$('#modal-content').innerHTML=`<div class="modal-head"><div><h2>${title}</h2>${subtitle?`<div class="modal-subtitle">${subtitle}</div>`:''}</div>${btn('','close-modal','ghost small','close')}</div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;modal.showModal()}
modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
const field=(label,name,value='',type='text',required=false,extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;
const area=(label,name,value='',rows=4)=>`<div class="field"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" rows="${rows}" maxlength="15000">${esc(value)}</textarea></div>`;
const selectField=(label,name,items,value='')=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${items.map(i=>`<option ${i===value?'selected':''}>${esc(i)}</option>`).join('')}</select></div>`;
const clientField=value=>`<div class="field"><label for="f-client">Client</label><select id="f-client" name="client">${clientOptions(value)}</select></div>`;
function datetimeLocal(iso){const d=iso?new Date(iso):new Date();return localDate(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}
function edit(kind,id='',prefill={}){const r=id?find(kind,id):prefill;if(!r)return;let fields='',title='';if(kind==='clients'){title='client';fields=`<div class="form-grid">${field('Client / business name','name',r.name,'text',true,'maxlength="120"')}${field('Project name','project',r.project)}${field('Email','email',r.email,'email')}${field('Contact person / phone','contact',r.contact)}${selectField('Status','status',['Active','On Hold','Completed'],r.status)}</div>${area('Instructions & preferences','instructions',r.instructions)}`}
 if(kind==='tasks'){title='task';fields=field('Task title','title',r.title,'text',true,'maxlength="200"')+`<div class="form-grid">${clientField(r.client)}${field('Due date','due',r.due,'date')}${selectField('Status','status',statuses,r.status||'To Do')}${selectField('Priority','priority',['Normal','Medium','High'],r.priority)}</div>`+area('Notes','notes',r.notes)}
 if(kind==='events'){title='meeting';fields=field('Meeting title','title',r.title,'text',true)+clientField(r.client)+`<div class="form-grid">${field('Start (your device’s local time)','start',datetimeLocal(r.start),'datetime-local',true)}${field('End (your device’s local time)','end',datetimeLocal(r.end||new Date(Date.now()+3600000).toISOString()),'datetime-local',true)}</div>`+field('Meeting link / venue','venue',r.venue)+area('Meeting notes','notes',r.notes)+(!id&&integrations.calendar?.connected?'<label class="checkbox-label"><input type="checkbox" name="google">Create in Google Calendar instead of local calendar</label><p class="quiet mt">The event will appear under “View Google events”.</p>':'')}
 if(kind==='time'){title='time entry';fields=field('Work description','title',r.title,'text',true)+clientField(r.client)+`<div class="form-grid">${field('Date','date',r.date||currentDay(),'date',true)}${field('Minutes worked','minutes',r.seconds?Number((r.seconds/60).toFixed(2)):'','number',true,'min="0.02" max="1440" step="0.01"')}</div>`}
 if(kind==='reports'){title='daily report';fields=field('Report date','date',r.date||currentDay(),'date',true)+`<div class="form-grid">${area('Completed work','completed',r.completed)}${area('Pending items','pending',r.pending)}${area('Blockers','blockers',r.blockers)}${area('Next steps','next',r.next)}</div>`+field('Tracked time (minutes)','minutes',r.seconds?Math.round(r.seconds/60):0,'number',true,'min="0" max="10080"')}
 if(kind==='templates'){title='template / SOP';fields=field('Title','title',r.title,'text',true)+selectField('Category','category',['Email Template','SOP','Notes'],r.category)+area('Content','body',r.body,9)}
 if(kind==='files'){title='file / app link';fields=field('Title','title',r.title,'text',true)+field('HTTPS link','url',r.url,'url',true,'pattern="https://.*"')+field('Category','category',r.category||'File')}
 if(kind==='checklist'){title='checklist item';fields=field('Checklist item','title',r.title,'text',true)}
 showModal(`${id?'Edit':'Add'} ${title}`,`<form id="record-form">${fields}<div class="form-error" role="alert"></div></form>`,(id?btn('Delete','delete:'+kind+':'+id,'danger small','trash'):'')+btn('Cancel','close-modal')+`<button class="primary" type="submit" form="record-form">Save ${title}</button>`);
 $('#record-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;if(button.disabled)return;button.disabled=true;$('.form-error',e.target).textContent='';try{const b={...r,...Object.fromEntries(new FormData(e.target))};if(kind==='events'){b.start=new Date(b.start).toISOString();b.end=new Date(b.end).toISOString();if(new Date(b.end)<=new Date(b.start))throw Error('Meeting end must be after its start.')}if(kind==='time'||kind==='reports'){b.seconds=Math.round(Number(b.minutes)*60);delete b.minutes}if(b.google){await api('/api/google/calendar','POST',b);modal.close();toast('Meeting created in Google Calendar.');return}await save(kind,b);modal.close();render();toast('Saved successfully.')}catch(err){$('.form-error',e.target).textContent=err.message}finally{button.disabled=false}}
}
function confirmDialog(title,message,action,label='Confirm'){showModal(title,`<p>${esc(message)}</p>`,btn('Cancel','close-modal')+btn(label,action,'primary'))}
async function remove(kind,id){await api('/api/records/'+kind+'/'+id,'DELETE');data[kind]=getList(kind).filter(r=>r.id!==id);modal.close();render();toast('Record deleted.')}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copy(text){if(!text)throw Error('Generate or enter content first.');try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{showModal('Copy text',`<textarea readonly rows="12">${esc(text)}</textarea>`);$('textarea',modal).select()}}
function reportPrefill(){const today=currentDay(),done=getList('tasks').filter(t=>t.status==='Completed'&&dayOf(t.updatedAt||t.createdAt)===today),pending=getList('tasks').filter(t=>t.status!=='Completed');return{date:today,completed:done.map(t=>'• '+t.title+' ('+cname(t.client)+')').join('\n'),pending:pending.map(t=>'• '+t.title).join('\n'),blockers:pending.filter(t=>t.status==='Waiting for Client').map(t=>'• '+t.title).join('\n'),next:pending.filter(t=>t.status==='To Do').slice(0,5).map(t=>'• '+t.title).join('\n'),seconds:getList('time').filter(t=>t.date===today).reduce((n,t)=>n+Number(t.seconds),0)}}
async function timer(action){const x=await api('/api/timer','POST',{action,title:$('#timer-title')?.value||timerState()?.title||'',client:$('#timer-client')?.value||timerState()?.client||'',date:currentDay()});data.timer=x.timer;data.time=x.time;render();if(action==='stop')toast('Work session saved to your timesheet.');}
async function removeQuiet(k,id){await api('/api/records/'+k+'/'+id,'DELETE');data[k]=getList(k).filter(r=>r.id!==id)}
function compose(prefill={}){showModal('Review your email',`<form id="compose-form">${field('Recipient email','to',prefill.to,'email',true)}${field('Subject','subject',prefill.subject,'text',true)}${area('Message','body',prefill.body,10)}<p class="quiet">This sends a real email through your connected Gmail account. Review the recipient and message.</p><div class="form-error" role="alert"></div></form>`,btn('Cancel','close-modal')+btn('Save draft','save-email-draft')+'<button type="submit" class="primary" form="compose-form">Send email</button>');$('#compose-form').onsubmit=e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));confirmDialog('Send this email?',`Send “${b.subject}” to ${b.to}?`,'confirm-send','Send now');compose.pending=b}}
async function loadGmailInbox(showConfirmation=false){
 const messages=await api('/api/gmail');
 mails=messages;
 selectedMail=messages.find(message=>message.id===selectedMail?.id)||messages[0]||null;
 if(page==='inbox')render();
 if(showConfirmation)toast('Inbox refreshed.');
}
function loadGmailOnOpen(){
 if(page==='inbox'&&integrations.gmail?.connected){
  loadGmailInbox().catch(error=>toast(error.message,true));
 }
}
function setupHelp(){showModal('Connection setup',`<p>Your core workspace works independently. To enable external apps, configure the server settings described in <strong>SETUP.md</strong> inside your project ZIP.</p><ol class="help-list"><li>Create Google OAuth web app credentials and enable Gmail, Calendar, Drive and Sheets APIs.</li><li>Set GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET and a permanent ENCRYPTION_KEY on the server.</li><li>Register this callback: <strong>${esc(location.origin)}/auth/google/callback</strong>.</li><li>Add your Google account as a test user while the OAuth app is in testing.</li><li>For AI, set OPENAI_API_KEY and OPENAI_MODEL. API billing is separate from ChatGPT.</li><li>Restart your server, then select Connect account.</li></ol><p class="quiet">GitHub stores the source. This app requires a Node.js 24 server and a persistent disk; GitHub Pages cannot run its backend.</p>`,btn('Got it','close-modal','primary'))}
function workspace(id){const c=find('clients',id);if(!c)return;const tasks=getList('tasks').filter(t=>t.client===id);showModal(esc(c.name),`<p class="muted">${esc(c.project||'Client workspace')}</p><div class="instructions">${esc(c.instructions||'No instructions yet.')}</div><div class="divider"></div><h3>Tasks</h3>${tasks.map(taskLine).join('')||'<p class="muted">No tasks assigned yet.</p>'}<div class="divider"></div><h3>Tracked time</h3><p>${duration(getList('time').filter(t=>t.client===id).reduce((n,t)=>n+Number(t.seconds),0))}</p>`,btn('Edit client','edit:clients:'+id)+btn('Add task','client-task:'+id,'primary'))}
function detail(kind,id){const r=find(kind,id);if(!r)return toast('This item could not be found.',true);const ignored=new Set(['id','_version','sample','createdAt','updatedAt']);const names={client:'Client',title:'Title',name:'Name',due:'Due date',status:'Status',priority:'Priority',project:'Project',instructions:'Instructions',contact:'Contact',email:'Email',seconds:'Duration',start:'Starts',end:'Ends',body:'Content',notes:'Notes',date:'Date',url:'Link',category:'Category',completed:'Completed work',pending:'Pending items',blockers:'Blockers',next:'Next steps',to:'Recipient',subject:'Subject'};showModal(esc(r.title||r.name||r.subject||'Record details'),Object.entries(r).filter(([k,v])=>!ignored.has(k)&&v!==''&&v!=null).map(([k,v])=>`<div class="field"><label>${esc(names[k]||k)}</label><div class="report-content">${esc(k==='client'?cname(v):k==='seconds'?duration(v):['start','end'].includes(k)?dateStr(v)+' · '+clockStr(v):v)}</div></div>`).join(''),btn('Close','close-modal','primary'),previewMode?'Sample information · Read-only preview':'Record details');}
async function sampleData(){if(getList('tasks').length||getList('clients').length)throw Error('Sample data can only be added to an empty workspace.');const a=await save('clients',{name:'BrightPath Marketing',project:'Marketing & admin support',email:'alex@example.com',contact:'Alex · Sample client',status:'Active',instructions:'Sample: manage inbox, update CRM, and coordinate campaigns.',sample:true}),b=await save('clients',{name:'Summit Digital',project:'Content & reporting',email:'sarah@example.com',contact:'Sarah · Sample client',status:'Active',instructions:'Sample: assist with content planning and weekly reporting.',sample:true}),c=await save('clients',{name:'Nova Realty',project:'Lead research',email:'mike@example.com',status:'Active',instructions:'Sample: research leads and prepare a weekly summary.',sample:true});for(const t of [{title:'Reply to client emails',client:a.id,status:'To Do',priority:'High'},{title:'Update CRM records',client:a.id,status:'In Progress',priority:'Medium'},{title:'Research 20 leads',client:c.id,status:'To Do',priority:'High'},{title:'Prepare daily report',client:b.id,status:'In Progress',priority:'Medium'},{title:'Approval of updated landing page',client:a.id,status:'Waiting for Client',priority:'High'},{title:'Feedback on content plan',client:b.id,status:'Waiting for Client',priority:'Medium'},{title:'Schedule next review meeting',client:b.id,status:'Completed',priority:'Normal'}])await save('tasks',{...t,due:currentDay(),sample:true});for(const [h,title,client]of [[10,'Client check-in',a.id],[14,'Project review',b.id],[17,'Prepare daily report','']]){const d=new Date();d.setHours(h,0,0,0);await save('events',{title,client,start:d.toISOString(),end:new Date(+d+1800000).toISOString(),sample:true})}await save('templates',{title:'Client follow-up email',category:'Email Template',body:'Hi [Name],\n\nI’m following up on [item]. Please let me know if you have any updates or need anything from me.\n\nThank you,\nCliff',sample:true});await save('templates',{title:'Client onboarding checklist',category:'SOP',body:'1. Confirm scope and working hours.\n2. Record communication preferences.\n3. Receive authorized access.\n4. Agree on reporting schedule.\n5. Add initial tasks.',sample:true});for(const title of ['Review inbox and calendar','Choose today’s top three priorities','Update task statuses','Prepare end-of-day report'])await save('checklist',{title,sample:true});toast('Clearly labelled sample records added.');render()}
async function action(name,button){if(name==='pages-help'){showModal('Workspace connection',`<p>The design is available to preview. Your private account and database still need to be connected before you can save work or link apps.</p><p class="muted">No real client records or accounts are connected in this preview.</p>`,btn('Close','close-modal','primary'));return}if(previewMode&&!['goto','menu','close-modal','startday','notifications','workspace','template-view','template-copy','setup-help','report-preview','month-prev','month-next','month-now','edit','detail','ai-preset','finishday','drafts-view','draft-open','mail','mail-task','google-calendar','google-drive'].includes(name.split(':')[0])){await action('pages-help',button);return}const [type,kind,id]=name.split(':');if(type==='detail'||(previewMode&&type==='edit')){detail(kind,id);return}if(previewMode&&type==='finishday'){const r=reportPrefill();showModal('Daily report preview',`<div class="report-content">${esc(reportText(r))}</div>`,btn('Close','close-modal','primary'),'Sample data · Nothing is saved');return}if(previewMode&&type==='google-calendar'){showModal('Calendar preview',getList('events').map(e=>`<div class="task-line"><div><h3>${esc(e.title)}</h3><p class="muted">${dateStr(e.start)} · ${clockStr(e.start)}</p>${btn('View meeting','detail:events:'+e.id,'small')}</div></div>`).join('')||'<p>No sample meetings.</p>',btn('Close','close-modal'),'Sample meetings · Google is not connected');return}if(previewMode&&type==='google-drive'){navigate('templates');tab='files';render();return}if(previewMode&&type==='mail-task'){detail('tasks','sample-1');return}if(previewMode&&type==='draft-open'){detail('drafts',kind);return}if(type==='toggle-password'){const f=$('#password');if(f){f.type=f.type==='password'?'text':'password';button.textContent=f.type==='password'?'Show':'Hide'}return}if(type==='menu'){$('.sidebar')?.classList.toggle('open');$('.mobile-overlay')?.classList.toggle('open');return}if(type==='goto'){navigate(kind);return}if(type==='close-modal'){modal.close();return}if(type==='add'){edit(kind);return}if(type==='edit'){edit(kind,id);return}if(type==='delete'){confirmDialog('Delete this record?','This permanently removes the selected record. Other records are preserved.','remove:'+kind+':'+id,'Delete');return}if(type==='remove'){await remove(kind,id);return}if(type==='workspace'){workspace(kind);return}if(type==='client-task'){edit('tasks','',{client:kind});return}if(type==='add-task-status'){edit('tasks','',{status:statuses[Number(kind)]});return}if(type==='add-followup'){edit('tasks','',{status:'Waiting for Client'});return}if(type==='complete'){const t=find('tasks',kind);await save('tasks',{...t,status:t.status==='Completed'?'To Do':'Completed'});render();toast('Task updated.');if(modal.open&&modal.textContent.includes('Tasks'))modal.close();return}if(type==='checklist'){const c=find('checklist',kind);await save('checklist',{...c,doneDate:c.doneDate===currentDay()?'':currentDay()});render();return}if(type==='startday'){const pending=getList('tasks').filter(t=>t.status!=='Completed'&&(!t.due||t.due<=currentDay())),meet=getList('events').filter(e=>dayOf(e.start)===currentDay());showModal('A calm start to your day.',`<p class="muted">${pending.length} priorities · ${meet.length} meetings · ${getList('tasks').filter(t=>t.status==='Waiting for Client').length} waiting for client</p>${pending.slice(0,6).map(taskLine).join('')||'<p>Your task list is clear. Add your first priority.</p>'}<div class="divider"></div><h3>Daily checklist</h3>${getList('checklist').map(c=>`<div class="task-line"><button class="check ${c.doneDate===currentDay()?'done':''}" data-action="checklist:${c.id}" aria-label="Toggle checklist item">${c.doneDate===currentDay()?icon('check'):''}</button>${esc(c.title)}</div>`).join('')||'<p class="muted">Add a reusable checklist in Templates & Files.</p>'}`,btn('Ready to focus','close-modal','primary'));return}if(type==='finishday'){edit('reports','',reportPrefill());return}if(type==='timer-discard-request'){confirmDialog('Discard this work session?','The active timer will be cleared without adding a timesheet entry.','timer-discard','Discard');return}if(type==='timer-discard'){await timer('discard');modal.close();toast('Active session discarded.');return}if(type.startsWith('timer-')){await timer(type.slice(6));return}if(type==='month-prev'||type==='month-next'){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+(type==='month-prev'?-1:1),1);render();return}if(type==='month-now'){calendarMonth=new Date();render();return}if(type==='report-preview'){const r=find('reports',kind);showModal('Daily work report',`<div class="report-content">${esc(reportText(r))}</div>`,btn('Export TXT','report-export:'+kind,'small','download')+btn('Print / save PDF','print-report','primary','files'));return}if(type==='print-report'){const contents=$('.report-content',modal)?.textContent||'';const w=window.open('','_blank');if(!w)throw Error('Allow pop-ups to print your report.');w.document.write('<!doctype html><title>Daily Work Report</title><body><pre></pre></body>');w.document.querySelector('pre').textContent=contents;w.document.close();w.print();return}if(type==='report-export'){download('Daily-Report-'+find('reports',kind).date+'.txt',reportText(find('reports',kind)));return}if(type==='time-export'){const csv=x=>'"'+String(x??'').replaceAll('"','""').replace(/^[=+@-]/,"'$&")+'"';download('Timesheet-'+currentDay()+'.csv','Date,Client,Task,Seconds\r\n'+getList('time').map(t=>[t.date,cname(t.client),t.title,t.seconds].map(csv).join(',')).join('\r\n'),'text/csv');return}if(type==='template-view'){const r=find('templates',kind);showModal(esc(r.title),`<div class="report-content">${esc(r.body)}</div>`,btn('Copy text','template-copy:'+kind,'primary','files'));return}if(type==='template-copy'){await copy(find('templates',kind).body);return}if(type==='ai-copy'){await copy(aiText);return}if(type==='ai-save'){if(!aiText)throw Error('Generate a draft first.');edit('templates','',{title:'AI draft · '+currentDay(),body:aiText,category:'Notes'});return}if(type==='ai-preset'){aiPrompt=kind==='email'?'Draft a professional email to [client] about [topic].\n\nDetails:\n':kind==='meeting'?'Turn these meeting notes into clear action items with suggested owners and deadlines. Mark missing details as unspecified.\n\nNotes:\n':'Summarize the following notes into key points and next steps.\n\nNotes:\n';if(page==='ai')render();else navigate('ai');return}if(type==='setup-help'){setupHelp();return}if(type==='gmail-setup'){
 const issues=integrations.gmail?.setupIssues||[];
 showModal('Set up Gmail connection',`${issues.length?`<p><strong>Production settings to fix</strong></p><ul>${issues.map(issue=>`<li>${esc(issue)}</li>`).join('')}</ul>`:''}<p>Enable Gmail API in Google Cloud and create a Web application OAuth client.</p><p>Set its authorized redirect URI to <strong>${esc(location.origin)}/auth/google/callback</strong>.</p><p>In Cloudflare Pages Production settings, add GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET and a permanent 64-character hexadecimal ENCRYPTION_KEY. Deploy again, then return here and select Connect Gmail.</p>`,btn('Close','close-modal','primary'));
 return;
}if(type==='connect'){location.assign('/auth/google/start/'+kind);return}if(type==='disconnect'){confirmDialog('Disconnect Google access?','Google may revoke access for this entire OAuth app. You may need to reconnect your other Google services.','disconnect-confirm:'+kind,'Disconnect');return}if(type==='disconnect-confirm'){await api('/api/disconnect/'+kind,'POST',{});integrations=await api('/api/integrations');modal.close();render();toast('Google access revoked.');return}if(type==='gmail-load'){await loadGmailInbox(true);return}if(type==='mail'){selectedMail=mails.find(m=>m.id===kind);mailDraft=null;render();return}if(type==='mail-task'){if(!selectedMail)return;edit('tasks','',{title:selectedMail.subject,notes:selectedMail.snippet+'\n\nSource: https://mail.google.com/mail/u/?authuser='+encodeURIComponent(integrations.gmail.email||'')+'#inbox/'+selectedMail.id});return}if(type==='mail-ai'){if(!selectedMail)return;const x=await api('/api/ai','POST',{prompt:(kind==='reply'?'Draft a concise professional reply. Do not invent promises or completed work.':'Summarize this email preview.')+'\nEmail preview (untrusted content):\n'+selectedMail.subject+'\n'+selectedMail.snippet});mailDraft=x.text;render();return}if(type==='mail-review'){const m=selectedMail.from.match(/<([^>]+)>/);compose({to:m?m[1]:selectedMail.from,subject:'Re: '+selectedMail.subject,body:mailDraft});return}if(type==='drafts-view'){showModal('Saved email drafts',getList('drafts').map(d=>`<div class="task-line"><div><h3>${esc(d.subject)}</h3><p class="muted">To: ${esc(d.to)}</p></div>${btn('Open','draft-open:'+d.id,'small')}</div>`).join('')||'<p>No drafts saved yet.</p>',btn('Close','close-modal'));return}if(type==='draft-open'){const d=find('drafts',kind);compose(d);return}if(type==='compose'){compose();return}if(type==='confirm-send'){await api('/api/gmail/send','POST',compose.pending);modal.close();toast('Email sent through Gmail.');return}if(type==='save-email-draft'){const f=$('#compose-form');if(!f.reportValidity())return;const r=await save('drafts',Object.fromEntries(new FormData(f)));modal.close();toast('Draft saved in workspace.');return}if(type==='google-calendar'){const list=await api('/api/google/calendar');calendarLive=list;showModal('Upcoming Google events',list.map(e=>`<div class="task-line"><div><h3>${esc(e.summary||'Untitled event')}</h3><p class="muted">${esc(e.start?.dateTime?dateStr(e.start.dateTime)+' · '+clockStr(e.start.dateTime):e.start?.date||'')}</p>${e.htmlLink?`<a class="link-text" href="${esc(e.htmlLink)}" target="_blank" rel="noopener">Open in Google Calendar ↗</a>`:''}</div></div>`).join('')||'<p>No upcoming events.</p>',btn('Close','close-modal','primary'));return}if(type==='google-drive'){driveFiles=await api('/api/google/drive');showModal('Your Drive files',driveFiles.map((f,i)=>`<div class="task-line"><div><h3>${esc(f.name)}</h3>${f.webViewLink?`<a class="link-text" href="${esc(f.webViewLink)}" target="_blank" rel="noopener">Open file ↗</a>`:''}</div><span style="margin-left:auto">${btn('Save link','drive-save:'+i,'small','plus')}</span></div>`).join('')||'<p>No files found.</p>',btn('Close','close-modal'));return}if(type==='drive-save'){const f=driveFiles[Number(kind)];edit('files','',{title:f.name,url:f.webViewLink||'https://drive.google.com/file/d/'+f.id+'/view',category:'Google Drive'});return}if(type==='google-sheets'){showModal('Google Sheets tracker',`<form id="sheets-form">${field('Spreadsheet ID (from its URL)','spreadsheet','','text',true)}${field('Range','range','Sheet1!A1:D20','text',true)}<button type="submit" class="primary">Read range</button></form><div id="sheets-result" class="report-content mt"></div><div class="divider"></div><h3>Append rows</h3><p class="quiet">Enter rows as a JSON array, for example: [["Cliff", "Completed", "2026-11-07"]]. This writes to your actual sheet.</p><textarea id="sheet-values" aria-label="Rows to append as JSON" rows="3"></textarea><div class="mt">${btn('Review append','sheet-append','small','plus')}</div>`,btn('Close','close-modal'));$('#sheets-form').onsubmit=e=>{e.preventDefault();withBusy(e.submitter,async()=>{const b=Object.fromEntries(new FormData(e.target)),x=await api('/api/google/sheets','POST',b);$('#sheets-result').textContent=(x.values||[]).map(r=>r.join('  |  ')).join('\n')||'No values in this range.'})};return}if(type==='sheet-append'){const b=Object.fromEntries(new FormData($('#sheets-form')));try{b.values=JSON.parse($('#sheet-values').value)}catch{throw Error('Enter a valid JSON array of rows.')}if(!Array.isArray(b.values)||!b.values.every(r=>Array.isArray(r)&&r.every(v=>['string','number','boolean'].includes(typeof v))))throw Error('Use an array of rows containing text, numbers, or booleans.');action.sheetPending=b;confirmDialog('Append rows to your sheet?',`Add ${b.values.length} rows to the specified spreadsheet?`,'sheet-confirm','Append rows');return}if(type==='sheet-confirm'){await api('/api/google/sheets/append','POST',action.sheetPending);modal.close();toast('Rows appended to Google Sheets.');return}if(type==='app-shortcut'){edit('files','',{category:'App shortcut'});return}if(type==='backup'){await load();download('VA-Workspace-Backup-'+currentDay()+'.json',JSON.stringify({exportedAt:new Date().toISOString(),profile:{name:user.name,email:user.email,timezone:user.timezone},records:data},null,2),'application/json');return}if(type==='history'){const x=await api('/api/data');data.history=x.history;showModal('Work history',(data.history||[]).map(h=>`<div class="task-line"><div>${esc(h.message)}<div class="quiet">${dateStr(h.time)} · ${clockStr(h.time)}</div></div>`).join('')||'<p>No activity yet.</p>',btn('Close','close-modal'));return}if(type==='notifications'){const reminders=getList('events').filter(e=>Date.parse(e.start)>Date.now()&&Date.parse(e.start)-Date.now()<86400000),overdue=getList('tasks').filter(t=>t.status!=='Completed'&&t.due&&t.due<=currentDay());showModal('Your reminders',reminders.map(e=>`<div class="reminder">${esc(e.title)} · ${clockStr(e.start)}</div>`).join('')+overdue.map(t=>`<div class="task-line">${icon('tasks')}<div>${esc(t.title)}<div class="muted">Due ${dateStr(t.due)}</div></div></div>`).join('')||'<p>All caught up. No reminders right now.</p>',btn('Close','close-modal'));return}if(type==='sample'){confirmDialog('Explore with sample data?','Add clearly labelled sample clients, tasks, meetings, and templates to your empty workspace?','sample-confirm','Load samples');return}if(type==='sample-confirm'){modal.close();await sampleData();return}if(type==='logout'){await api('/api/auth/logout','POST',{});user=null;data={};mails=[];selectedMail=null;aiText='';aiPrompt='';mailDraft=null;csrf='';location.hash='';auth(false);return}}
// Centralized delegated handlers avoid accumulating listeners during navigation.
document.addEventListener('click',e=>{const nav=e.target.closest('button[data-page]');if(nav){navigate(nav.dataset.page);return}const button=e.target.closest('[data-action]');if(!button)return;e.preventDefault();withBusy(button,()=>action(button.dataset.action,button))});
