 data={clients:[{id:'sample-client',name:'BrightPath Marketing',project:'Sample admin support project',email:'alex@example.com',status:'Active',instructions:'Sample: manage inbox and coordinate campaigns.',sample:true},{id:'sample-client-2',name:'Summit Digital',project:'Sample reporting project',email:'sarah@example.com',status:'Active',sample:true}],tasks:[{id:'sample-1',title:'Reply to client emails',client:'sample-client',status:'To Do',priority:'High',due:today,sample:true},{id:'sample-2',title:'Update CRM records',client:'sample-client',status:'In Progress',priority:'Medium',due:today,sample:true},{id:'sample-3',title:'Prepare daily report',client:'sample-client-2',status:'To Do',priority:'Medium',due:today,sample:true},{id:'sample-4',title:'Approval of updated landing page',client:'sample-client',status:'Waiting for Client',priority:'High',due:today,sample:true}],events:[{id:'sample-meeting',title:'Sample client check-in',client:'sample-client',start:at(10),end:new Date(Date.parse(at(10))+1800000).toISOString()}],time:[{id:'sample-time',title:'Sample lead research',client:'sample-client',date:today,seconds:15600}],templates:[{id:'sample-template',title:'Client follow-up email',category:'Email Template',body:'Hi [Name],\nI’m following up on [item]. Please let me know if you have any updates.\nThank you,\nCliff'}]};
 data.reports=[{id:'sample-report',date:today,completed:'• Reviewed sample client emails\n• Updated sample CRM records',pending:'• Landing page approval',blockers:'Waiting for client feedback',next:'• Prepare next week’s priorities',seconds:15600,sample:true}];data.files=[{id:'sample-file',title:'Weekly report resource',category:'Sample file link',url:'https://docs.google.com/',sample:true}];data.checklist=[{id:'sample-check',title:'Review inbox and calendar',sample:true},{id:'sample-check-2',title:'Choose today’s top priorities',sample:true}];data.drafts=[{id:'sample-draft',to:'alex@example.com',subject:'Weekly progress update',body:'Hi Alex,\nHere is a sample progress update for review.\nThank you, Cliff',sample:true}];mails=[{id:'sample-mail',subject:'Weekly progress update',from:'Alex <alex@example.com>',snippet:'Hi Cliff, could you prepare the weekly report with completed tasks, current status, and next steps? This is a sample email.'}];selectedMail=mails[0];
